import{_ as l,r as a,o as c,c as r,e as t,a as n,s as e}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Области фильтрации - October CMS - 3.x","titleTemplate":false,"description":"Узнайте, как фильтровать списки с помощью областей.","frontmatter":{"subtitle":"Узнайте, как фильтровать списки с помощью областей."},"headers":[{"level":2,"title":"Доступные области","slug":"доступные-области","link":"#доступные-области","children":[]},{"level":2,"title":"Свойства областей","slug":"своиства-областеи","link":"#своиства-областеи","children":[{"level":3,"title":"Применение областей модели","slug":"применение-областеи-модели","link":"#применение-областеи-модели","children":[]},{"level":3,"title":"Зависимости областей","slug":"зависимости-областеи","link":"#зависимости-областеи","children":[]}]}],"relativePath":"3.x/ru/element/filter-scopes.md","filePath":"3.x/ru/element/filter-scopes.md"}'),i={name:"3.x/ru/element/filter-scopes.md"};function u(d,s,k,g,y,m){const p=a("pre-heading"),o=a("post-heading");return c(),r("div",null,[t(p),s[0]||(s[0]=n("h1",null,"Области фильтрации",-1)),t(o),s[1]||(s[1]=e(`<p>Области фильтрации — это определения областей, используемые фильтрами, часто совместно со списком. Подобно столбцам списка, на них ссылаются следующие области:</p><ul><li><a href="./../extend/lists/list-controller.html">Контроллер списков</a></li><li><a href="./../extend/forms/relation-controller.html">Контроллер отношений</a></li></ul><p>Все области фильтрации идентифицируются по их индивидуальному свойству <strong>type</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">scopes</span><span class="token punctuation">:</span>
    <span class="token key atrule">myscope</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> date
        <span class="token comment"># ...</span>
</code></pre></div><h2 id="доступные-области"><a href="#доступные-области" class="header-anchor">#</a> Доступные области</h2><p>Доступны следующие области фильтрации:</p>`,6)),s[2]||(s[2]=n("div",{class:"content-list-p",markdown:"1"},[n("p",null,[n("a",{href:"./filter/scope-checkbox.html"},"Checkbox"),n("a",{href:"./filter/scope-switch.html"},"Switch"),n("a",{href:"./filter/scope-text.html"},"Text"),n("a",{href:"./filter/scope-number.html"},"Number"),n("a",{href:"./filter/scope-dropdown.html"},"Dropdown"),n("a",{href:"./filter/scope-group.html"},"Group"),n("a",{href:"./filter/scope-date.html"},"Date")])],-1)),s[3]||(s[3]=e(`<h2 id="своиства-областеи"><a href="#своиства-областеи" class="header-anchor">#</a> Свойства областей</h2><p>Для каждой области можно указать следующие свойства (где применимо).</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>имя при отображении области фильтрации пользователю.</td></tr><tr><td><strong>type</strong></td><td>определяет, как должна отображаться эта область. По умолчанию: <code>group</code>.</td></tr><tr><td><strong>conditions</strong></td><td>включает или отключает функции условий или задаёт необработанное условие where для применения к каждому условию, подробнее см. определение типа области.</td></tr><tr><td><strong>modelClass</strong></td><td>класс модели для использования как источника данных и ссылки для вызова локальных методов.</td></tr><tr><td><strong>modelScope</strong></td><td>задаёт метод <a href="./../extend/database/model.html">области запроса модели</a>, определённый в <strong>модели списка</strong>, для применения к запросу списка. Первый аргумент будет содержать объект запроса (как в обычном методе области), а второй аргумент — определение области, включая её заполненные значения.</td></tr><tr><td><strong>options</strong></td><td>опции для использования при фильтрации по нескольким элементам, предоставленные как массив.</td></tr><tr><td><strong>optionsMethod</strong></td><td>запрашивает опции из имени метода, определённого в модели или как статический метод, например <code>Class::method</code>.</td></tr><tr><td><strong>emptyOption</strong></td><td>необязательная метка для намеренного пустого выбора.</td></tr><tr><td><strong>default</strong></td><td>значение по умолчанию для фильтра: массив, строка или целое число в зависимости от значения фильтра.</td></tr><tr><td><strong>permissions</strong></td><td><a href="./../extend/backend/permissions.html">разрешения</a>, которые должен иметь текущий пользователь панели управления для использования области фильтрации. Поддерживает строку для одного разрешения или массив разрешений, из которых достаточно одного для предоставления доступа.</td></tr><tr><td><strong>dependsOn</strong></td><td>строка или массив имён других областей, от которых зависит эта область. При изменении других областей эта область будет сброшена.</td></tr><tr><td><strong>nameFrom</strong></td><td>имя атрибута модели, используемого для отображения метки фильтра. По умолчанию: <code>name</code>.</td></tr><tr><td><strong>valueFrom</strong></td><td>определяет атрибут модели для использования в качестве исходного значения. По умолчанию берётся из имени области.</td></tr><tr><td><strong>order</strong></td><td>числовой вес при определении порядка отображения, значение по умолчанию увеличивается на 100 пунктов за область.</td></tr><tr><td><strong>after</strong></td><td>поместить эту область после другой существующей области по имени, используя порядок отображения (+1).</td></tr><tr><td><strong>before</strong></td><td>поместить эту область перед другой существующей областью по имени, используя порядок отображения (-1).</td></tr></tbody></table></div><h3 id="применение-областеи-модели"><a href="#применение-областеи-модели" class="header-anchor">#</a> Применение областей модели</h3><p>Большинство фильтров применяют свои ограничения с использованием разумных значений по умолчанию. Свойство <code>modelScope</code> может использоваться для применения пользовательских ограничений к запросу фильтра с помощью <a href="./../extend/database/model.html">определения метода области модели</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">myfilter</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> My Filter
    <span class="token key atrule">type</span><span class="token punctuation">:</span> group
    <span class="token key atrule">modelScope</span><span class="token punctuation">:</span> applyMyFilter
</code></pre></div><p>В приведённом примере мы ожидаем отношение на первичной модели с именем <strong>myfilter</strong> и метод <strong>scopeApplyMyFilter</strong>, определённый на связанной модели. Второй аргумент содержит определение области, включая её заполненные значения.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">scopeApplyMyFilter</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$scope</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">whereIn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my_filter_attribute&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token keyword type-casting">array</span><span class="token punctuation">)</span> <span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">value</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Свойство <code>modelScope</code> также может быть определено как статический метод PHP-класса (<code>Class::method</code>).</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">myfilter</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> My Filter
    <span class="token key atrule">type</span><span class="token punctuation">:</span> group
    <span class="token key atrule">modelScope</span><span class="token punctuation">:</span> <span class="token string">&quot;App\\MyCustomClass::applyMyFilter&quot;</span>
</code></pre></div><p>В этом примере метод должен быть объявлен статически на указанном классе.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">App</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">MyCustomClass</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">function</span> <span class="token function-definition function">applyMyFilter</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$scope</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">whereIn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my_filter_attribute&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token keyword type-casting">array</span><span class="token punctuation">)</span> <span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">value</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="зависимости-областеи"><a href="#зависимости-областеи" class="header-anchor">#</a> Зависимости областей</h3><p>Свойство <code>dependsOn</code> позволяет связывать несколько фильтров вместе. При изменении зависимости область фильтрации сбрасывается для применения новых условий. Рассмотрим следующий пример двух определений областей.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">country</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Country
    <span class="token key atrule">type</span><span class="token punctuation">:</span> group

<span class="token key atrule">state</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> State
    <span class="token key atrule">type</span><span class="token punctuation">:</span> group
    <span class="token key atrule">dependsOn</span><span class="token punctuation">:</span> country
    <span class="token key atrule">optionsMethod</span><span class="token punctuation">:</span> getCityOptionsForFilter
</code></pre></div><p>Область state зависит от значения области country, и опции фильтруются в PHP с помощью метода <strong>getCityOptionsForFilter</strong>. Первый аргумент этого метода будет содержать полный набор определений областей, включая их текущие значения.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getCityOptionsForFilter</span><span class="token punctuation">(</span><span class="token variable">$scopes</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$scopes</span><span class="token operator">-&gt;</span><span class="token property">country</span> <span class="token operator">&amp;&amp;</span> <span class="token punctuation">(</span><span class="token variable">$countryIds</span> <span class="token operator">=</span> <span class="token variable">$scopes</span><span class="token operator">-&gt;</span><span class="token property">country</span><span class="token operator">-&gt;</span><span class="token property">value</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token keyword static-context">self</span><span class="token operator">::</span><span class="token function">whereIn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;country_id&#39;</span><span class="token punctuation">,</span> <span class="token variable">$countryIds</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">lists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">return</span> <span class="token keyword static-context">self</span><span class="token operator">::</span><span class="token function">lists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,17))])}const v=l(i,[["render",u]]);export{f as __pageData,v as default};
